@if($admin)<div class="two-col"><section class="panel"><div class="panel-head"><h2>Expenses by category</h2><a href="/reports?report=category">Report →</a></div><div class="panel-body">@forelse($categoryTotals as $name=>$amount)<div class="mb-3"><div class="d-flex justify-content-between mb-2"><span>{{$name}}</span><span>৳ {{\App\Support\Money::format($amount)}}</span></div><div class="progress" role="progressbar" aria-label="{{$name}}" aria-valuenow="{{$amount}}" aria-valuemin="0" aria-valuemax="{{max(1,$categoryTotals->max())}}" style="height:7px"><div class="progress-bar" style="background:#39896b;width:{{$amount/max(1,$categoryTotals->max())*100}}%"></div></div></div>@empty<div class="empty">Category totals will appear after your first expense.</div>@endforelse</div></section><section class="panel"><div class="panel-head"><h2>Outstanding member balances</h2><a href="/reports?report=due">Due report →</a></div><div class="panel-body">@php($dues=$balances->filter(fn($b)=>$b['balance']<0)) @php($maxDue=max(1,-($dues->min('balance')??0))) @forelse($dues as $b)<div class="mb-3"><div class="d-flex justify-content-between mb-2"><span>{{$b['member']->name}}</span><span>৳ {{\App\Support\Money::format(-$b['balance'])}}</span></div><div class="progress" style="height:7px"><div class="progress-bar" style="background:#c9a45e;width:{{-$b['balance']/$maxDue*100}}%"></div></div></div>@empty<div class="empty">No outstanding balances.</div>@endforelse</div></section></div>@endif
<section class="panel"><div class="panel-head"><div><h2>Monthly collection</h2><p class="subtitle">Payments received each month</p></div><a href="/reports?report=collection">Collection report →</a></div><div class="panel-body chart-wrap"><div class="chart" style="height:125px">@php($collectionMax=max(1,$months->max('collection'))) @foreach($months as $month)<div class="bar-group"><div class="bar" style="width:40px;height:{{max(1,$month['collection']/$collectionMax*100)}}%" title="BDT {{\App\Support\Money::format($month['collection'])}}"></div><label>{{\Carbon\Carbon::parse($month['month'].'-01')->format('M')}} · {{\App\Support\Money::format($month['collection'])}}</label></div>@endforeach</div></div></section>
